For production form validation with domain verification:

```typescript
import dns from 'dns/promises';

interface EmailValidation {
  valid: boolean;
  reason?: 'format' | 'domain' | 'mx';
}

async function validateEmail(email: string): Promise<EmailValidation> {
  // Format check
  const formatRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!formatRe.test(email)) {
    return { valid: false, reason: 'format' };
  }

  const domain = email.split('@')[1];

  // Domain exists check
  try {
    await dns.lookup(domain);
  } catch {
    return { valid: false, reason: 'domain' };
  }

  // MX record check (can receive email)
  try {
    const mx = await dns.resolveMx(domain);
    if (mx.length === 0) {
      return { valid: false, reason: 'mx' };
    }
  } catch {
    return { valid: false, reason: 'mx' };
  }

  return { valid: true };
}
```

This checks format, domain existence, and MX records. The MX check confirms the domain can actually receive email. Want me to add this to your form validation utils?

