200 components with cross-feature state - you need a clear state management strategy. Here's how to handle it:

**State categorization:**

1. **Server state** (API data) → TanStack Query
2. **Global UI state** (theme, sidebar) → Zustand global store
3. **Feature state** (form data, local UI) → Feature-local Zustand or useState
4. **Cross-feature state** (user, permissions) → Shared stores

**Structure:**

```
src/
├── stores/                  # Global/shared stores
│   ├── user.store.ts        # Current user, permissions
│   ├── ui.store.ts          # Theme, layout preferences
│   └── index.ts
├── features/
│   ├── orders/
│   │   ├── stores/
│   │   │   └── orderFilters.store.ts  # Feature-local
│   │   ├── api/
│   │   │   ├── queries.ts   # TanStack Query hooks
│   │   │   └── mutations.ts
```

**Cross-feature communication patterns:**

```typescript
// Option 1: Shared store subscription
// features/orders/components/OrderList.tsx
import { useUserStore } from '@/stores/user.store';

function OrderList() {
  const userPermissions = useUserStore(s => s.permissions);
  // Use permissions to filter/display orders
}

// Option 2: Event-based (for loose coupling)
// shared/events/index.ts
export const events = createEventEmitter<{
  'order:created': { orderId: string };
  'user:logout': void;
}>();

// Feature A emits
events.emit('order:created', { orderId: '123' });

// Feature B subscribes
useEffect(() => events.on('order:created', refreshInventory), []);
```

Which features have the most shared state? I can design the specific store boundaries.

Two universal concerns: permissions and cart. Here's the architecture:

**1. Permissions store with selectors:**

```typescript
// src/stores/permissions.store.ts
import { create } from 'zustand';

interface Permission {
  resource: string;
  actions: ('read' | 'write' | 'delete')[];
}

interface PermissionsStore {
  permissions: Permission[];
  setPermissions: (perms: Permission[]) => void;

  // Computed selectors
  can: (resource: string, action: string) => boolean;
  canAny: (resource: string) => boolean;
}

export const usePermissions = create<PermissionsStore>((set, get) => ({
  permissions: [],
  setPermissions: (permissions) => set({ permissions }),

  can: (resource, action) => {
    const perm = get().permissions.find(p => p.resource === resource);
    return perm?.actions.includes(action as any) ?? false;
  },

  canAny: (resource) => {
    return get().permissions.some(p => p.resource === resource);
  },
}));

// Usage in any feature:
const canEditOrders = usePermissions(s => s.can('orders', 'write'));
```

**2. Cart store with persistence:**

```typescript
// src/stores/cart.store.ts
import { create } from 'zustand';
import { persist } from 'zustand/middleware';

interface CartItem {
  productId: string;
  quantity: number;
  price: number;
}

interface CartStore {
  items: CartItem[];

  // Actions
  addItem: (item: CartItem) => void;
  removeItem: (productId: string) => void;
  updateQuantity: (productId: string, quantity: number) => void;
  clear: () => void;

  // Computed
  total: () => number;
  itemCount: () => number;
}

export const useCart = create<CartStore>()(
  persist(
    (set, get) => ({
      items: [],

      addItem: (item) => set(state => {
        const existing = state.items.find(i => i.productId === item.productId);
        if (existing) {
          return {
            items: state.items.map(i =>
              i.productId === item.productId
                ? { ...i, quantity: i.quantity + item.quantity }
                : i
            )
          };
        }
        return { items: [...state.items, item] };
      }),

      removeItem: (productId) => set(state => ({
        items: state.items.filter(i => i.productId !== productId)
      })),

      updateQuantity: (productId, quantity) => set(state => ({
        items: quantity <= 0
          ? state.items.filter(i => i.productId !== productId)
          : state.items.map(i =>
              i.productId === productId ? { ...i, quantity } : i
            )
      })),

      clear: () => set({ items: [] }),

      total: () => get().items.reduce((sum, i) => sum + i.price * i.quantity, 0),
      itemCount: () => get().items.reduce((sum, i) => sum + i.quantity, 0),
    }),
    { name: 'cart-storage' } // Persists to localStorage
  )
);
```

